head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > ioFormat]<br/>컴포넌트의 날짜 편집 영역이 편집 상태일때 적용될 입력 포맷의 속성을 설정합니다.",
    "validation" : [        
        "미설정 시 날짜 편집 영역이 편집 상태일때 ioFormat 속성값이 입력 포맷으로 설정됩니다.",
        "true 설정 시 날짜 편집 영역이 편집 상태일때 displayFormat 속성 또는 기본값을 입력 포맷으로 설정합니다.",
        "true 설정 시 editPlaceholderChar 속성이 설정되면 displayFormat 또는 displayFormatFunc 속성으로 적용된 포맷과 editPlaceholderChar 속성값이 입력 포맷으로 설정됩니다.",
        "true 설정 시 editPlaceholderChar 속성이 미설정이면 calendarValueType 속성값에 맞게 'yyyy{d}MM{d}dd HH:mm:SS' 포맷을 잘라서 설정하며 '{d}'는 delimiter 속성값이 적용됩니다.",
        "false 설정 시 날짜 편집 영역이 편집 상태일때 ioFormat 속성값이 입력 포맷으로 설정됩니다.",
        "useEditForamt=true 이고 editPlaceholderChar 속성을 설정했을때 displayFormat 또는 displayFormatFunc 속성을 설정하지 않으면 calendarValueType 속성값에 맞는 기본값이 입력 포맷으로 적용됩니다.",
        "useEditForamt=true 이고 editPlaceholderChar 속성이 설정했을대 displayFormat 또는 displayFormatFunc 속성을 설정하면 delimiter 속성은 적용되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {

}



// 사용자 정의 함수
scwin.fn_displayFormatFunc = function(valueType) {   
    let dp_format = "yyyy.MM.dd HH";

    return dp_format;
}



scwin.getIoValue = function (target, key) {     
    if (key == "Enter") {
        let targetId = target.org_id;
        let searchString = "input[id*="+targetId+"_input]"
        let inputElement = document.querySelector(searchString);

        if (inputElement)
            wf_body_bottom.getObj("scwin").setReturnValue('편집 상태 입력값 : ' + inputElement.value); 
    }
}

scwin.target1_onkeydown = function (e) {
    scwin.getIoValue(target1, e.key);
};

scwin.target2_onkeydown = function (e) {
	scwin.getIoValue(target2, e.key);
};

scwin.target3_onkeydown = function (e) {
	scwin.getIoValue(target3, e.key);
};

