	scwin.getIoValue(target4, e.key);
};

scwin.target5_onkeydown = function (e) {
	scwin.getIoValue(target5, e.key);	
};

scwin.target6_onkeydown = function (e) {
	scwin.getIoValue(target6, e.key);
